{
  "version": "1",
  "text": "You are dressed in a chocolate satin blouse with voluminous sleeves and a peplum waist, paired with straight camel trousers. A navy blue double-breasted blazer is worn over the top for structure and warmth, while your wrists and ears are adorned with delicate gold jewelry and pearl-encrusted earrings. A grey scarf adds texture to your ensemble, complemented by chocolate ankle boots and a vibrant red handbag.",
  "how_to_wear": [
    "Wear the blazer open over the blouse to show off the peplum silhouette and waist definition."
  ],
  "about_items": [
    {
      "n": "#13·30",
      "text": "This chocolate satin blouse features a V-neck design, voluminous sleeves that add drama, and a flattering peplum waist with a gathered detail. Its smooth fabric creates an elegant drape."
    },
    {
      "n": "#238·31",
      "text": "These straight camel trousers offer a clean line and comfortable fit, crafted from semi-wool for a sophisticated yet cozy feel in autumn weather."
    },
    {
      "n": "#479·11",
      "text": "The navy blue double-breasted blazer adds structure to your look with its sharp lapels and classic button placement. Its deep color contrasts beautifully with the lighter tones of your other pieces."
    },
    {
      "n": "#297·20",
      "text": "This beige belt cinches the waist at a natural point, creating an hourglass silhouette that enhances your figure while adding a polished touch to any outfit."
    },
    {
      "n": "#484·01",
      "text": "The grey wool coat with black and pink plaid brings warmth and visual interest. Its classic cut ensures it is versatile enough for various occasions, from casual outings to more formal events."
    }
  ]
}
